-- bricx.memberships_guard (ADR 0084; owner additions A2, A5): what a
-- CHECK cannot hold, for every role, the superuser included. is_external
-- is fixed at creation. A membership whose role is the system owner role
-- is never temporary (expires_at) and never external: checked on INSERT
-- and on every UPDATE, so neither a promotion to owner nor an expiry set
-- on an owner passes. The role is read as the invoker (bricx_app sees its
-- org's roles; bricx_owner through roles_owner_select); a role the
-- statement cannot see is refused when the row is temporary or external
-- (fail closed). SQLSTATE P606B.
CREATE FUNCTION "bricx"."memberships_guard"() RETURNS trigger
  LANGUAGE plpgsql SECURITY INVOKER AS $$
DECLARE
  v_key text;
  v_found boolean;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.is_external IS DISTINCT FROM OLD.is_external THEN
    RAISE EXCEPTION 'a membership keeps its external flag'
      USING ERRCODE = 'P606B';
  END IF;
  IF NEW.is_external OR NEW.expires_at IS NOT NULL THEN
    SELECT r.system_key, true INTO v_key, v_found
      FROM bricx.roles r WHERE r.org_id = NEW.org_id AND r.id = NEW.role_id;
    IF v_found IS NOT TRUE OR v_key = 'owner' THEN
      RAISE EXCEPTION 'an owner is neither temporary nor external'
        USING ERRCODE = 'P606B';
    END IF;
  END IF;
  RETURN NEW;
END
$$;
--> statement-breakpoint
CREATE TRIGGER "memberships_guard" BEFORE INSERT OR UPDATE ON "bricx"."memberships" FOR EACH ROW EXECUTE FUNCTION "bricx"."memberships_guard"();
--> statement-breakpoint
-- bricx.project_memberships_guard (ADR 0084): a project membership whose
-- role is the system owner role is never temporary, and never held by an
-- external member (the org membership's flag). SQLSTATE P606B.
CREATE FUNCTION "bricx"."project_memberships_guard"() RETURNS trigger
  LANGUAGE plpgsql SECURITY INVOKER AS $$
DECLARE
  v_key text;
BEGIN
  SELECT r.system_key INTO v_key
    FROM bricx.roles r WHERE r.org_id = NEW.org_id AND r.id = NEW.role_id;
  IF v_key = 'owner' AND (
       NEW.expires_at IS NOT NULL
       OR EXISTS (SELECT 1 FROM bricx.memberships m
                  WHERE m.org_id = NEW.org_id AND m.user_id = NEW.user_id
                    AND m.removed_at IS NULL AND m.is_external)) THEN
    RAISE EXCEPTION 'an owner is neither temporary nor external'
      USING ERRCODE = 'P606B';
  END IF;
  RETURN NEW;
END
$$;
--> statement-breakpoint
CREATE TRIGGER "project_memberships_guard" BEFORE INSERT OR UPDATE ON "bricx"."project_memberships" FOR EACH ROW EXECUTE FUNCTION "bricx"."project_memberships_guard"();
--> statement-breakpoint
-- bricx.invitations_guard v2 (ADR 0084, A5; amends ADR 0077 C6): as
-- 0013, and is_external and membership_expires_at never change.
CREATE OR REPLACE FUNCTION "bricx"."invitations_guard"() RETURNS trigger
  LANGUAGE plpgsql SECURITY INVOKER AS $$
BEGIN
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.org_id IS DISTINCT FROM OLD.org_id
     OR NEW.project_id IS DISTINCT FROM OLD.project_id
     OR NEW.role_id IS DISTINCT FROM OLD.role_id
     OR NEW.project_role_id IS DISTINCT FROM OLD.project_role_id
     OR NEW.invited_by IS DISTINCT FROM OLD.invited_by
     OR NEW.created_at IS DISTINCT FROM OLD.created_at
     OR NEW.is_external IS DISTINCT FROM OLD.is_external
     OR NEW.membership_expires_at IS DISTINCT FROM OLD.membership_expires_at THEN
    RAISE EXCEPTION 'an invitation keeps its identity'
      USING ERRCODE = 'P6006';
  END IF;
  IF OLD.status <> 'pending' THEN
    RAISE EXCEPTION 'a settled invitation is final'
      USING ERRCODE = 'P6006';
  END IF;
  IF NEW.email_normalised IS DISTINCT FROM OLD.email_normalised
     AND NOT (NEW.email_normalised IS NULL AND NEW.status = 'accepted') THEN
    RAISE EXCEPTION 'an invitation keeps its address until accepted'
      USING ERRCODE = 'P6006';
  END IF;
  RETURN NEW;
END
$$;
