-- The stream sources (ADR 0084, C1; CLAUDE.md rule 3). No PowerSync
-- stream exists before P8-02; these views are what the placeholders
-- <<user_project_access>> and <<user_grants>> of the generated
-- sync-streams.yaml stand for, so a suspended or expired member is out of
-- every stream scope from the day streams exist. security_invoker: the
-- reader's own RLS applies (bricx_app sees its org; the replication role
-- of P8-02 is granted there). Plain views store no rows.
-- app.active_memberships: the one SQL definition of an active org
-- membership (rls.ts activeMembershipSql).
CREATE VIEW "app"."active_memberships" WITH (security_invoker = true) AS
  SELECT m.id, m.org_id, m.user_id, m.role_id, m.is_external
  FROM bricx.memberships m
  WHERE m.removed_at IS NULL AND m.suspended_at IS NULL AND (m.expires_at IS NULL OR m.expires_at > now());
--> statement-breakpoint
-- app.active_project_memberships: an active project membership of an
-- active org member.
CREATE VIEW "app"."active_project_memberships" WITH (security_invoker = true) AS
  SELECT pm.id, pm.org_id, pm.project_id, pm.user_id, pm.role_id, pm.overrides, m.is_external
  FROM bricx.project_memberships pm
  JOIN app.active_memberships m ON m.org_id = pm.org_id AND m.user_id = pm.user_id
  WHERE pm.removed_at IS NULL AND pm.suspended_at IS NULL AND (pm.expires_at IS NULL OR pm.expires_at > now());
--> statement-breakpoint
-- app.user_project_access (user_id, project_id): the projects a user is
-- an active member of. Org-wide reach (an org-scope key on a project
-- resource) is not expanded here: P8-02 adds it from app.user_grants_source.
CREATE VIEW "app"."user_project_access" WITH (security_invoker = true) AS
  SELECT pm.org_id, pm.user_id, pm.project_id
  FROM app.active_project_memberships pm;
--> statement-breakpoint
-- app.user_grants_source (user_id, permission, scope, target_id): what
-- buildAccess() computes per request, as rows (apps/api
-- stream-sources.int.test.ts compares the two). The system owner role is
-- one row with permission '*': its bundle is the whole catalogue, which
-- lives in code. An external member's org role keeps org-scope keys of
-- app.external_org_keys() only, no own-scope key and no org-scope
-- elevation. Keys the catalogue does not know are not filtered here.
CREATE VIEW "app"."user_grants_source" WITH (security_invoker = true) AS
  WITH org_role AS (
    SELECT m.org_id, m.user_id, m.is_external, r.id AS role_id, r.system_key
    FROM app.active_memberships m
    JOIN bricx.roles r ON r.org_id = m.org_id AND r.id = m.role_id AND r.archived_at IS NULL
  ), org_key AS (
    SELECT o.org_id, o.user_id, o.is_external, rp.permission AS key
    FROM org_role o
    JOIN bricx.role_permissions rp ON rp.org_id = o.org_id AND rp.role_id = o.role_id AND rp.revoked_at IS NULL
    WHERE o.system_key IS DISTINCT FROM 'owner'
  ), project_role AS (
    SELECT pm.id, pm.org_id, pm.user_id, pm.project_id, pm.overrides, r.id AS role_id, r.system_key
    FROM app.active_project_memberships pm
    JOIN bricx.roles r ON r.org_id = pm.org_id AND r.id = pm.role_id
  ), project_key AS (
    SELECT p.id, p.org_id, p.user_id, p.project_id, rp.permission AS key
    FROM project_role p
    JOIN bricx.role_permissions rp ON rp.org_id = p.org_id AND rp.role_id = p.role_id AND rp.revoked_at IS NULL
    WHERE p.system_key IS DISTINCT FROM 'owner'
      AND NOT EXISTS (SELECT 1 FROM bricx.roles a WHERE a.org_id = p.org_id AND a.id = p.role_id AND a.archived_at IS NOT NULL)
      AND NOT COALESCE(jsonb_typeof(p.overrides -> 'remove') = 'array' AND (p.overrides -> 'remove') ? rp.permission, false)
    UNION
    SELECT p.id, p.org_id, p.user_id, p.project_id, added.key
    FROM project_role p
    CROSS JOIN LATERAL jsonb_array_elements_text(
      CASE WHEN jsonb_typeof(p.overrides -> 'add') = 'array' THEN p.overrides -> 'add' ELSE '[]'::jsonb END
    ) AS added(key)
    WHERE p.system_key IS DISTINCT FROM 'owner'
  ), elevation AS (
    SELECT g.org_id, g.user_id, m.is_external, g.permission AS key, g.scope_id, g.site_id
    FROM bricx.access_grants g
    JOIN app.active_memberships m ON m.org_id = g.org_id AND m.user_id = g.user_id
    WHERE g.revoked_at IS NULL AND g.starts_at <= now() AND now() < g.expires_at
  )
  SELECT o.org_id, o.user_id, '*'::text AS permission, 'org'::text AS scope, NULL::uuid AS target_id
    FROM org_role o WHERE o.system_key = 'owner'
  UNION
  SELECT k.org_id, k.user_id, left(k.key, length(k.key) - 4), 'org', NULL::uuid
    FROM org_key k
    WHERE k.key LIKE '%.org' AND (NOT k.is_external OR k.key = ANY (app.external_org_keys()))
  UNION
  SELECT k.org_id, k.user_id, left(k.key, length(k.key) - 4), 'own', NULL::uuid
    FROM org_key k WHERE k.key LIKE '%.own' AND NOT k.is_external
  UNION
  SELECT p.org_id, p.user_id, '*', 'project', p.project_id
    FROM project_role p WHERE p.system_key = 'owner'
  UNION
  SELECT k.org_id, k.user_id, left(k.key, length(k.key) - 8), 'project', k.project_id
    FROM project_key k WHERE k.key LIKE '%.project'
  UNION
  SELECT k.org_id, k.user_id, left(k.key, length(k.key) - 4), 'own', NULL::uuid
    FROM project_key k WHERE k.key LIKE '%.own'
  UNION
  SELECT k.org_id, k.user_id, left(k.key, length(k.key) - 5), 'site', s.id
    FROM project_key k
    JOIN bricx.project_membership_sites a ON a.org_id = k.org_id AND a.project_membership_id = k.id AND a.removed_at IS NULL
    JOIN bricx.sites s ON s.org_id = a.org_id AND s.project_id = a.project_id AND s.id = a.site_id
    WHERE k.key LIKE '%.site' AND (s.archived_at IS NULL OR k.key LIKE '%.read.site')
  UNION
  SELECT e.org_id, e.user_id, left(e.key, length(e.key) - 4), 'org', NULL::uuid
    FROM elevation e
    WHERE e.key LIKE '%.org' AND e.scope_id IS NULL AND e.site_id IS NULL AND NOT e.is_external
  UNION
  SELECT e.org_id, e.user_id, left(e.key, length(e.key) - 8), 'project', e.scope_id
    FROM elevation e
    WHERE e.key LIKE '%.project' AND e.scope_id IS NOT NULL AND e.site_id IS NULL
  UNION
  SELECT e.org_id, e.user_id, left(e.key, length(e.key) - 5), 'site', e.site_id
    FROM elevation e
    JOIN bricx.sites s ON s.org_id = e.org_id AND s.project_id = e.scope_id AND s.id = e.site_id
    WHERE e.key LIKE '%.site' AND e.scope_id IS NOT NULL AND e.site_id IS NOT NULL
      AND (s.archived_at IS NULL OR e.key LIKE '%.read.site');
--> statement-breakpoint
