-- app.memberships_due() (ADR 0084): the 5-minute sweep's cross-org read
-- of open memberships past expires_at whose expiry is not recorded yet
-- (oldest first, at most p_limit, 1000 at most), org and project rows;
-- the worker records each one as bricx_app in its org with its audit
-- event. Writes nothing. SECURITY DEFINER as bricx_owner through the
-- owner read policies of 0006; EXECUTE for bricx_relay only, as
-- app.access_grants_due().
CREATE FUNCTION "app"."memberships_due"(p_limit integer)
RETURNS TABLE (kind text, id uuid, org_id uuid, user_id uuid)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
BEGIN ATOMIC
  SELECT d.kind, d.id, d.org_id, d.user_id FROM (
    SELECT 'org'::text AS kind, m.id, m.org_id, m.user_id, m.expires_at
    FROM bricx.memberships m
    WHERE m.removed_at IS NULL AND m.expired_at IS NULL AND m.expires_at IS NOT NULL AND m.expires_at <= now()
    UNION ALL
    SELECT 'project'::text, pm.id, pm.org_id, pm.user_id, pm.expires_at
    FROM bricx.project_memberships pm
    WHERE pm.removed_at IS NULL AND pm.expired_at IS NULL AND pm.expires_at IS NOT NULL AND pm.expires_at <= now()
  ) d
  ORDER BY d.expires_at, d.id
  LIMIT LEAST(GREATEST(COALESCE(p_limit, 0), 0), 1000);
END;
--> statement-breakpoint
REVOKE ALL ON FUNCTION "app"."memberships_due"(integer) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION "app"."memberships_due"(integer) TO bricx_relay;
--> statement-breakpoint
-- app.memberships_expiring() (ADR 0084, C8): open memberships that
-- expire within p_days (1..90) and have no notice yet, soonest first.
-- The sweep writes one memberships.expiring outbox event for each.
-- Writes nothing. EXECUTE for bricx_relay only.
CREATE FUNCTION "app"."memberships_expiring"(p_days integer, p_limit integer)
RETURNS TABLE (kind text, id uuid, org_id uuid, user_id uuid)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
BEGIN ATOMIC
  SELECT d.kind, d.id, d.org_id, d.user_id FROM (
    SELECT 'org'::text AS kind, m.id, m.org_id, m.user_id, m.expires_at
    FROM bricx.memberships m
    WHERE m.removed_at IS NULL AND m.expired_at IS NULL AND m.expiry_notified_at IS NULL
      AND m.expires_at > now()
      AND m.expires_at <= now() + make_interval(days => LEAST(GREATEST(COALESCE(p_days, 0), 1), 90))
    UNION ALL
    SELECT 'project'::text, pm.id, pm.org_id, pm.user_id, pm.expires_at
    FROM bricx.project_memberships pm
    WHERE pm.removed_at IS NULL AND pm.expired_at IS NULL AND pm.expiry_notified_at IS NULL
      AND pm.expires_at > now()
      AND pm.expires_at <= now() + make_interval(days => LEAST(GREATEST(COALESCE(p_days, 0), 1), 90))
  ) d
  ORDER BY d.expires_at, d.id
  LIMIT LEAST(GREATEST(COALESCE(p_limit, 0), 0), 1000);
END;
