-- audit_events (ADR 0084, C7): the member activity read. Narrow, both
-- lead with org_id and end with seq. A plain CREATE INDEX inside this
-- transaction blocks audit inserts for the build: acceptable only while
-- the table is near empty (before launch). Any later index on this table
-- is built CONCURRENTLY outside a transaction (P13-01 Also line).
CREATE INDEX "audit_events_by_actor" ON "bricx"."audit_events" USING btree ("org_id","actor_id","seq" DESC NULLS LAST);
